// 테마 CSS 변수를 인라인 style 객체로 반환합니다.
// dark(다크 모드 여부)와 vnAlpha(대사창 투명도, 0~1)까지 함께 받아서
// 화면 전체 색을 이 한 곳에서 결정합니다.
function themeVars(t, dark = false, vnAlpha = 0.55) {
  const surface = t.surface || (dark ? "#161a20" : "#ffffff");
  return {
    "--accent": t.accent,
    "--accent-soft": t.accentSoft,
    "--accent-deep": t.accentDeep,
    "--bg-panel": t.bgPanel,
    "--border": t.border,
    "--border-soft": t.borderSoft,
    "--surface": surface,
    "--bg": surface,
    "--bg-card": surface,
    "--text": dark ? "#e7edf3" : "#223142",
    "--text-dim": dark ? "#a6b7c5" : "#647c8c",
    "--text-faint": dark ? "#7b8d9c" : "#9db2c0",
    "--glass": dark ? "rgba(18,22,28,0.82)" : "rgba(255,255,255,0.85)",
    "--vn-bg": dark ? `rgba(16,20,26,${vnAlpha})` : `rgba(255,255,255,${vnAlpha})`,
    "--backdrop": dark ? "rgba(0,0,0,0.55)" : "rgba(30,60,80,0.28)",
    background: surface,
    colorScheme: dark ? "dark" : "light",
  };
}

// ---- 컬러 팔레트 임의 지정: 색 하나만 고르면 나머지(연한 배경/진한 강조색/테두리 등)를 자동 계산 ----
function hexToRgb(hex) {
  const h = hex.replace("#", "");
  const full = h.length === 3 ? h.split("").map(c => c + c).join("") : h;
  const n = parseInt(full, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function rgbToHex(r, g, b) {
  return "#" + [r, g, b].map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0")).join("");
}
// amount 0~1: target(흰색/검은색) 쪽으로 얼마나 섞을지
function mixColor(hex, targetHex, amount) {
  const [r1, g1, b1] = hexToRgb(hex);
  const [r2, g2, b2] = hexToRgb(targetHex);
  return rgbToHex(r1 + (r2 - r1) * amount, g1 + (g2 - g1) * amount, b1 + (b2 - b1) * amount);
}
function lightenColor(hex, amount) { return mixColor(hex, "#ffffff", amount); }
function darkenColor(hex, amount) { return mixColor(hex, "#000000", amount); }
function isValidHexColor(hex) { return /^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(hex); }
function deriveThemeFromColor(hex) {
  return {
    label: "커스텀",
    accent: hex,
    accentSoft: lightenColor(hex, 0.32),
    accentDeep: darkenColor(hex, 0.28),
    bgPanel: lightenColor(hex, 0.94),
    bgGrad1: lightenColor(hex, 0.88),
    bgGrad2: lightenColor(hex, 0.93),
    border: lightenColor(hex, 0.72),
    borderSoft: lightenColor(hex, 0.85),
  };
}

// ---- 다크 모드: 고른 테마색은 그대로 두고, 배경/테두리/글자색만 어둡게 뒤집습니다 ----
// (밝은 모드에서 accentDeep이 "더 진한 색"이었다면, 어두운 배경에서는 반대로
//  "더 밝은 색"이어야 글자가 잘 보이기 때문에 밝기 방향을 뒤집어 계산합니다.)
const DARK_BASE = "#12161c";
function toDarkTheme(t) {
  const a = t.accent;
  return {
    label: t.label,
    accent: lightenColor(a, 0.14),
    accentSoft: mixColor(a, DARK_BASE, 0.35),
    accentDeep: lightenColor(a, 0.45),
    bgPanel: mixColor(a, DARK_BASE, 0.87),
    bgGrad1: mixColor(a, DARK_BASE, 0.9),
    bgGrad2: mixColor(a, DARK_BASE, 0.93),
    border: mixColor(a, DARK_BASE, 0.68),
    borderSoft: mixColor(a, DARK_BASE, 0.79),
    surface: mixColor(a, DARK_BASE, 0.94),
  };
}

/* ============================== HELPERS ============================== */

function newId() { return Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8); }
// 캐릭터 이름 색깔: 올바른 색상 코드일 때만 사용하고, 아니면 빈 값(= 기본 테마색)으로 처리합니다.
function safeNameColor(c) {
  const v = (c || "").trim();
  return isValidHexColor(v) ? v : "";
}
// 헷갈리기 쉬운 문자(0/O, 1/I 등)를 뺀 6자리 초대 코드
function genInviteCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let s = "";
  for (let i = 0; i < 6; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return s;
}
function d100() { return Math.floor(Math.random() * 100) + 1; }
function rollN(n) { let s = 0; for (let i = 0; i < n; i++) s += Math.floor(Math.random() * 6) + 1; return s; }
function rollChar(key) {
  if (key === "SIZ" || key === "INT" || key === "EDU") return (rollN(2) + 6) * 5;
  return rollN(3) * 5;
}
function fmtDate(iso) {
  if (!iso) return "";
  try {
    const d = new Date(iso);
    return `${d.getFullYear()}.${String(d.getMonth()+1).padStart(2,"0")}.${String(d.getDate()).padStart(2,"0")}`;
  } catch { return iso; }
}
// new Date().toISOString()은 UTC 기준이라 한국 시간 자정~오전 9시 사이에는
// 하루 전 날짜로 계산되는 문제가 있어, 로컬(기기) 시간 기준으로 오늘 날짜를 구합니다.
function todayLocalISO() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}
function fmtTime(ts) {
  const d = new Date(ts);
  return `${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}`;
}
function emptyCharacteristics() { const o={}; CHAR_KEYS.forEach(k=>o[k]=50); return o; }
function emptySkills() { const o={}; SKILL_LIST.forEach(([n,b])=>o[n]=b); return o; }
function emptyDerived() { return {HP:10,maxHP:10,MP:10,maxMP:10,SAN:50,maxSAN:50,Luck:0}; }
function blankCharSheet(name="") { return {name,avatar:"",nameColor:"",characteristics:emptyCharacteristics(),skills:emptySkills(),customSkills:[],derived:emptyDerived(),notes:"",madness:{type:"",note:""}}; }
function blankProfile(name="") { return {name,avatar:""}; }

/* ============================== STORAGE (Firebase Firestore) ============================== */
// 기존에는 Claude 아티팩트 전용 API인 window.storage를 사용했으나,
// Netlify 등 일반 환경에는 window.storage가 없어 "저장소 없음" 에러가 발생했습니다.
// 아래는 동일한 함수 시그니처(storeGet/storeSet/storeDelete/storeListValues)를 유지한 채
// Firestore의 "kv" 컬렉션에 key-value로 저장하도록 교체한 버전입니다.
// shared 파라미터는 기존 호출부와의 호환을 위해 남겨두었을 뿐 실제로는 사용하지 않습니다
// (원본 코드가 어차피 모든 곳에서 shared:true로만 호출했기 때문에 컬렉션을 하나로 통일했습니다).

const KV_COLLECTION = "kv";

async function storeGet(key, _shared) {
  try {
    const snap = await getDoc(doc(db, KV_COLLECTION, key));
    if (!snap.exists()) return null;
    return snap.data().value;
  } catch { return null; }
}
async function storeSet(key, value, _shared) {
  let lastError = "";
  for (let i = 0; i < 3; i++) {
    try {
      await setDoc(doc(db, KV_COLLECTION, key), { value, updatedAt: Date.now() });
      return { ok: true };
    } catch (err) {
      lastError = err?.message || String(err);
      if (i < 2) await new Promise(r => setTimeout(r, 500));
    }
  }
  return { ok: false, error: lastError };
}
async function storeDelete(key, _shared) {
  try { await deleteDoc(doc(db, KV_COLLECTION, key)); return true; } catch { return false; }
}
async function storeListValues(prefix, _shared) {
  try {
    const col = collection(db, KV_COLLECTION);
    const q = query(col, orderBy("__name__"), startAt(prefix), endAt(prefix + "\uf8ff"));
    const snap = await getDocs(q);
    const out = [];
    snap.forEach(d => out.push({ key: d.id, value: d.data().value }));
    return out;
  } catch { return []; }
}
async function storeListKeys(prefix, _shared) {
  try {
    const col = collection(db, KV_COLLECTION);
    const q = query(col, orderBy("__name__"), startAt(prefix), endAt(prefix + "\uf8ff"));
    const snap = await getDocs(q);
    return { keys: snap.docs.map(d => d.id) };
  } catch { return { keys: [] }; }
}

// ---- 실시간 리스너 (onSnapshot) ----
// 기존 storeListValues/storeGet은 매번 전체를 다시 읽어오는 방식(폴링)이라
// Firestore 무료 요금제의 "하루 읽기 5만 건" 한도를 채팅이 길어질수록 빠르게 소모했습니다.
// onSnapshot은 최초 1회만 전체를 읽고, 그 뒤로는 "바뀐 문서"만 전송받기 때문에
// 폴링 대비 읽기 횟수가 크게 줄어듭니다. 반환값은 구독 해제 함수(unsubscribe)입니다.
function storeListenPrefix(prefix, onChange) {
  try {
    const col = collection(db, KV_COLLECTION);
    const q = query(col, orderBy("__name__"), startAt(prefix), endAt(prefix + "\uf8ff"));
    return onSnapshot(q, snap => {
      const out = [];
      snap.forEach(d => out.push({ key: d.id, value: d.data().value }));
      onChange(out);
    }, () => {});
  } catch { return () => {}; }
}
function storeListenDoc(key, onChange) {
  try {
    return onSnapshot(doc(db, KV_COLLECTION, key), snap => {
      onChange(snap.exists() ? snap.data().value : null);
    }, () => {});
  } catch { return () => {}; }
}

async function fileToResizedDataURL(file, maxSize=220) {
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=()=>{
      const img=new Image();
      img.onload=()=>{
        let {width,height}=img;
        if(width>height&&width>maxSize){height=Math.round(height*maxSize/width);width=maxSize;}
        else if(height>maxSize){width=Math.round(width*maxSize/height);height=maxSize;}
        const canvas=document.createElement("canvas");
        canvas.width=width;canvas.height=height;
        canvas.getContext("2d").drawImage(img,0,0,width,height);
        resolve(canvas.toDataURL("image/jpeg",0.9));
      };
      img.onerror=reject; img.src=reader.result;
    };
    reader.onerror=reject; reader.readAsDataURL(file);
  });
}
// 채팅으로 보내는 이미지는 PNG로 저장해 투명 배경(알파 채널)을 유지합니다.
async function fileToResizedPNG(file, maxSize=480) {
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=()=>{
      const img=new Image();
      img.onload=()=>{
        let {width,height}=img;
        if(width>height&&width>maxSize){height=Math.round(height*maxSize/width);width=maxSize;}
        else if(height>maxSize){width=Math.round(width*maxSize/height);height=maxSize;}
        const canvas=document.createElement("canvas");
        canvas.width=width;canvas.height=height;
        canvas.getContext("2d").drawImage(img,0,0,width,height);
        resolve(canvas.toDataURL("image/png"));
      };
      img.onerror=reject; img.src=reader.result;
    };
    reader.onerror=reject; reader.readAsDataURL(file);
  });
}

