// 숫자 입력창(능력치/기능치 등)에서 "080"처럼 앞자리 0이 화면에 남는 문제를 막아줍니다.
// React는 계산된 값(예: 8→08 로 타이핑해도 결국 8)이 바뀌지 않으면 화면 글자를 다시 안 그려서,
// 앞자리 0이 지워지지 않고 남는 경우가 있습니다. 그래서 이 함수가 입력 즉시 화면 글자 자체를
// 직접 정리해줍니다.
function stripLeadingZero(e){
  const cleaned=e.target.value.replace(/^0+(?=\d)/,"");
  if(cleaned!==e.target.value) e.target.value=cleaned;
  return cleaned;
}

function CharacteristicsGrid({characteristics,setCharacteristics,allowRoll,compact=false}){
  return(
    <div style={{display:"grid",gridTemplateColumns:compact?"repeat(2,1fr)":"repeat(4,1fr)",gap:7}}>
      {CHAR_KEYS.map(k=>(
        <div key={k} className="coc-stat-box">
          <div className="coc-label" style={{marginBottom:3}}>{CHAR_LABEL[k]} ({k})</div>
          <div style={{display:"flex",alignItems:"center",gap:3,justifyContent:"center"}}>
            <input className="coc-input coc-mono" type="number" value={characteristics[k]}
              onChange={e=>setCharacteristics({...characteristics,[k]:parseInt(stripLeadingZero(e))||0})}
              onWheel={e=>e.currentTarget.blur()}
              onFocus={e=>e.target.select()}
              style={{textAlign:"center",padding:"5px 3px",fontSize:15,color:"var(--accent-deep)"}}/>
            {allowRoll&&<button type="button" className="coc-btn ghost small" style={{padding:5}} onClick={()=>setCharacteristics({...characteristics,[k]:rollChar(k)})}><Dice5 size={11}/></button>}
          </div>
        </div>
      ))}
    </div>
  );
}

function DerivedStats({characteristics,derived,setDerived,allowRoll}){
  const recompute=()=>{
    const maxHP=Math.floor((characteristics.CON+characteristics.SIZ)/10);
    const maxMP=Math.floor(characteristics.POW/5);
    const maxSAN=Math.min(characteristics.POW,99);
    const Luck=rollN(3)*5;
    setDerived({HP:maxHP,maxHP,MP:maxMP,maxMP,SAN:maxSAN,maxSAN,Luck});
  };
  const rollLuck=()=>setDerived({...derived,Luck:rollN(3)*5});
  const field=(key,maxKey,label)=>(
    <div className="coc-stat-box">
      <div className="coc-label" style={{marginBottom:3,display:"flex",alignItems:"center",justifyContent:"center",gap:4}}>
        {label}
        {key==="Luck"&&allowRoll&&(
          <button type="button" onClick={rollLuck} title="(3d6)×5 굴리기"
            style={{background:"none",border:"none",cursor:"pointer",color:"var(--accent-deep)",padding:0,display:"flex"}}>
            <Dice5 size={11}/>
          </button>
        )}
      </div>
      <div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:2}}>
        <input className="coc-mono" type="number" value={derived[key]}
          onChange={e=>setDerived({...derived,[key]:parseInt(stripLeadingZero(e))||0})}
          onWheel={e=>e.currentTarget.blur()}
          onFocus={e=>e.target.select()}
          style={{width:40,background:"transparent",border:"none",color:"var(--accent-deep)",fontSize:16,textAlign:"right",outline:"none"}}/>
        {maxKey&&<><span style={{color:"var(--text-faint)"}}>/</span><span className="coc-mono" style={{fontSize:12.5,color:"var(--text-dim)"}}>{derived[maxKey]}</span></>}
      </div>
    </div>
  );
  return(
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:7}}>
        <div className="coc-label">파생 능력치</div>
        {allowRoll&&<button type="button" className="coc-btn ghost small" onClick={recompute}><RotateCcw size={11}/> 재계산</button>}
      </div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:7}}>
        {field("HP","maxHP","체력(HP)")}{field("MP","maxMP","정신(MP)")}{field("SAN","maxSAN","이성(SAN)")}{field("Luck",null,"행운")}
      </div>
    </div>
  );
}

function SkillsGrid({skills,setSkills,customSkills=[],setCustomSkills,readOnly=false,compact=false}){
  const [open,setOpen]=useState(false);

  const addCustom=()=>{
    setCustomSkills([...customSkills,{id:newId(),name:"",value:0}]);
  };
  const updateCustom=(id,patch)=>{
    setCustomSkills(customSkills.map(c=>c.id===id?{...c,...patch}:c));
  };
  const removeCustom=id=>{
    setCustomSkills(customSkills.filter(c=>c.id!==id));
  };

  return(
    <div>
      <button type="button" onClick={()=>setOpen(!open)}
        style={{display:"flex",alignItems:"center",gap:5,background:"none",border:"none",cursor:"pointer",color:"var(--accent-deep)",fontFamily:"JetBrains Mono,monospace",fontSize:12,padding:0,fontWeight:600}}>
        {open?<ChevronUp size={12}/>:<ChevronDown size={12}/>}
        기능치 {open?"숨기기":`펼치기 (${SKILL_LIST.length+customSkills.length})`}
      </button>
      {open&&(
        <>
          <div className="coc-scroll" style={{marginTop:9,maxHeight:280,overflowY:"auto",display:"grid",gridTemplateColumns:compact?"1fr":"repeat(2,1fr)",gap:5,paddingRight:4,paddingBottom:8}}>
            {SKILL_LIST_SORTED.map(([name])=>(
              <div key={name} style={{display:"flex",alignItems:"center",justifyContent:"space-between",background:"var(--bg-panel)",border:"1px solid var(--border-soft)",borderRadius:6,padding:"4px 7px"}}>
                <span style={{fontSize:13.5,color:"var(--text-dim)"}}>{name}</span>
                <input className="coc-mono" type="number" step={5} min={0} max={99} value={skills[name]??0} readOnly={readOnly}
                  onChange={e=>setSkills({...skills,[name]:Math.max(0,Math.min(99,parseInt(stripLeadingZero(e))||0))})}
                  onWheel={e=>e.currentTarget.blur()}
                  onFocus={e=>e.target.select()}
                  style={{width:52,background:"transparent",border:"none",color:"var(--text)",textAlign:"right",outline:"none",fontSize:13.5}}/>
              </div>
            ))}
          </div>

          {/* 자유 기능치: 필수 목록에 없는 기능치를 플레이어가 마음대로 추가 */}
          {(customSkills.length>0||!readOnly)&&(
            <div style={{marginTop:12}}>
              <div className="coc-label" style={{marginBottom:6}}>자유 기능치</div>
              {customSkills.length===0&&readOnly&&<div style={{fontSize:12.5,color:"var(--text-faint)"}}>없음</div>}
              <div style={{display:"grid",gridTemplateColumns:compact?"1fr":"repeat(2,1fr)",gap:5}}>
                {customSkills.map(c=>(
                  <div key={c.id} style={{display:"flex",alignItems:"center",gap:4,background:"var(--bg-panel)",border:"1px solid var(--border-soft)",borderRadius:6,padding:"4px 7px"}}>
                    {readOnly?(
                      <span style={{fontSize:13.5,color:"var(--text-dim)",flex:1}}>{c.name||"(이름 없음)"}</span>
                    ):(
                      <input value={c.name} onChange={e=>updateCustom(c.id,{name:e.target.value})}
                        placeholder="기능치 이름" style={{flex:1,background:"transparent",border:"none",outline:"none",fontSize:13.5,color:"var(--text)",minWidth:0}}/>
                    )}
                    <input className="coc-mono" type="number" step={5} min={0} max={99} value={c.value??0} readOnly={readOnly}
                      onChange={e=>updateCustom(c.id,{value:Math.max(0,Math.min(99,parseInt(stripLeadingZero(e))||0))})}
                      onWheel={e=>e.currentTarget.blur()}
                      onFocus={e=>e.target.select()}
                      style={{width:44,background:"transparent",border:"none",color:"var(--text)",textAlign:"right",outline:"none",fontSize:13.5,flexShrink:0}}/>
                    {!readOnly&&(
                      <button type="button" onClick={()=>removeCustom(c.id)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--text-faint)",padding:"0 2px",fontSize:14,lineHeight:1,flexShrink:0}}>×</button>
                    )}
                  </div>
                ))}
              </div>
              {!readOnly&&(
                <button type="button" onClick={addCustom}
                  style={{display:"flex",alignItems:"center",gap:4,marginTop:7,background:"none",border:"1px dashed var(--border)",borderRadius:6,padding:"5px 10px",cursor:"pointer",color:"var(--accent-deep)",fontSize:12.5}}>
                  <Plus size={12}/> 기능치 추가
                </button>
              )}
            </div>
          )}
        </>
      )}
    </div>
  );
}

// 교육(EDU)×4 만큼의 "기능 점수"를 배분한다고 가정하고, 기준값보다 올린 만큼을 사용량으로 계산합니다.
// (자유 기능치는 기준값이 없으므로 값 전체를 사용량으로 셉니다.)
function calcSkillPoints(sheet){
  const total=(sheet.characteristics?.EDU||0)*4;
  let spent=0;
  SKILL_LIST.forEach(([name,base])=>{
    const cur=sheet.skills?.[name]??base;
    if(cur>base) spent+=(cur-base);
  });
  (sheet.customSkills||[]).forEach(c=>{ if(c.value>0) spent+=c.value; });
  return {total,spent,remaining:total-spent};
}

